// Lightweight DOM/CSS stage: no WebGL context or continuous render loop.
export function mountTeachingStage(sheet,{ask,continueLesson}={}){
 const node=document.createElement('section');node.className='classroom-teaching-stage';node.setAttribute('aria-label','课堂现场');
 node.innerHTML=`<div class="teaching-stage-scene"><div class="teaching-windows" aria-hidden="true"><i></i><i></i></div><div class="teaching-floor" aria-hidden="true"></div><div class="teaching-board"><div class="teaching-board-heading"><img class="teaching-board-seal" src="/suda-seal.svg" alt="苏州大学校徽" width="32" height="32"><span>课堂现场</span><strong class="teaching-state">准备上课</strong></div><p class="teaching-topic"></p></div><div class="teaching-person teaching-teacher" aria-hidden="true"><i></i><b></b><span></span></div><div class="teaching-desks" aria-hidden="true"><div class="teaching-seat"><span class="teaching-pupil"><b></b><em></em><u></u></span><i></i></div><div class="teaching-seat"><span class="teaching-pupil"><b></b><em></em><u></u></span><i></i></div><div class="teaching-seat"><span class="teaching-pupil"><b></b><em></em><u></u></span><i></i></div><div class="teaching-seat"><span class="teaching-pupil"><b></b><em></em><u></u></span><i></i></div><div class="teaching-seat"><span class="teaching-pupil"><b></b><em></em><u></u></span><i></i></div><div class="teaching-seat"><span class="teaching-pupil"><b></b><em></em><u></u></span><i></i></div></div><div class="teaching-listening" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></div></div><div class="teaching-speech" hidden><span class="teaching-speaker"></span><p></p></div><div class="teaching-cast"><span data-role="teacher">教师</span><span data-role="student">模拟同学</span><span data-role="assistant">助教</span></div><div class="teaching-interaction" hidden><p></p><button type="button" data-stage="ask">请模拟同学发言</button><button type="button" data-stage="groups">分组讨论</button><button type="button" data-stage="review">作答互评</button><button type="button" data-stage="continue">继续上课</button></div>`;
 sheet.before(node);const state=node.querySelector('.teaching-state'),topic=node.querySelector('.teaching-topic'),interaction=node.querySelector('.teaching-interaction'),bubble=node.querySelector('.teaching-speech');
 for(const mode of ['ask','groups','review'])node.querySelector('[data-stage='+mode+']').onclick=async event=>{const button=event.currentTarget;button.disabled=true;try{await ask?.(interaction.querySelector('p').textContent,mode)}finally{button.disabled=false}};
 node.querySelector('[data-stage=continue]').onclick=()=>{interaction.hidden=true;continueLesson?.()};
 let detachAudio=()=>{};
 const labels={speech:'讲解',laser:'指示重点',spotlight:'看这里',discussion:'讨论',musicListen:'聆听','music-listen':'聆听',listen:'聆听',play_music:'聆听',quiz:'作答与批改'};
 return {node,followAudio(audio,text,role='teacher'){detachAudio();this.set('speech',text,role);const chunks=String(text).match(/[\s\S]{1,48}/g)||[''];const update=()=>{const duration=Number(audio.duration),at=Number(audio.currentTime)||0;const fraction=Number.isFinite(duration)&&duration>0?at/duration:at*4/Math.max(1,String(text).length);const chunk=chunks[Math.min(chunks.length-1,Math.floor(fraction*chunks.length))];topic.textContent=chunk;bubble.querySelector('p').textContent=chunk;};audio.addEventListener('timeupdate',update);audio.addEventListener('durationchange',update);detachAudio=()=>{audio.removeEventListener('timeupdate',update);audio.removeEventListener('durationchange',update)};update()},set(type,text='',role='teacher'){node.dataset.state=type;node.dataset.speaker=role;node.querySelectorAll('.teaching-seat').forEach((seat,i)=>seat.classList.toggle('is-speaking',role==='student'&&type==='speech'&&i===0));bubble.hidden=!(type==='speech'&&text);if(!bubble.hidden){bubble.querySelector('.teaching-speaker').textContent=role==='student'?'模拟同学':role==='assistant'?'助教':'教师';bubble.querySelector('p').textContent=text;}state.textContent=labels[type]||(/wb_/.test(type)?'板书':'课堂进行中');topic.textContent=String(text).replace(/<[^>]*>/g,'').slice(0,220);node.querySelectorAll('[data-role]').forEach(n=>n.classList.toggle('active',n.dataset.role===role));if(type==='discussion'){interaction.hidden=false;interaction.querySelector('p').textContent=text;}},stop(){node.dataset.state='idle';state.textContent='已暂停';},clear(){detachAudio();bubble.hidden=true;interaction.hidden=true;topic.textContent='';this.stop()},dispose(){detachAudio();node.remove()}};
}
